# Paper II General Ability Test, Part B General Knowledge, Section D: history
# of India, the freedom movement and the Constitution (about 20 percent).
# Static facts only, no office-holders. Key written first.
ITEMS = [
    # ---------- Practice Test 1 ----------
    S(1, 2, "Ancient India", "Most seals found at Harappan sites were made of:",
      ["Steatite", "Bronze", "Gold", "Terracotta painted with lac"],
      "Harappan seals were mostly cut from steatite (soapstone), then fired to harden them. Many show an animal, often a 'unicorn', above a short line of the undeciphered script."),
    S(1, 2, "Ancient India", "Which Gupta ruler took the title 'Vikramaditya' and defeated the Shakas of western India?",
      ["Chandragupta II", "Samudragupta", "Skandagupta", "Chandragupta I"],
      "Chandragupta II (about 380 to 415 CE) defeated the Western Kshatrapas (Shakas) and took the title Vikramaditya. The Chinese pilgrim Fa-Hien visited India in his reign."),
    S(1, 2, "Ancient India", "The Satavahana dynasty, which issued coins with the names of kings and their mothers, ruled mainly over:",
      ["The Deccan", "Kashmir", "Bengal", "The Punjab"],
      "The Satavahanas ruled the Deccan from about the 1st century BCE to the 3rd century CE, with centres such as Pratishthana (Paithan) and Amaravati. Kings such as Gautamiputra Satakarni named themselves after their mothers."),
    S(1, 2, "Medieval India", "Akbar built the Ibadat Khana at Fatehpur Sikri for:",
      ["Religious discussions between scholars of different faiths", "Storing the royal treasury", "Training the imperial cavalry", "Housing foreign ambassadors"],
      "The Ibadat Khana (House of Worship), built in 1575, hosted debates among Muslim, Hindu, Jain, Zoroastrian and Christian scholars. These led to Akbar's idea of sulh-i kul, peace with all."),
    S(1, 2, "Medieval India", "Which Delhi Sultan organised the iqta system and introduced the silver tanka and the copper jital?",
      ["Iltutmish", "Balban", "Alauddin Khalji", "Firoz Shah Tughlaq"],
      "Iltutmish (1211 to 1236) gave iqtas, the revenue of a territory, to his officers in place of salaries, and issued the silver tanka and copper jital that became the standard coins of the Sultanate."),
    S(1, 2, "Freedom movement", "In 1928 the Nehru Report, a draft constitution prepared by Indian leaders, demanded:",
      ["Dominion status for India", "Complete independence at once", "A separate state for the princely states", "The end of all elections"],
      "The committee chaired by Motilal Nehru asked for dominion status within the Empire. The younger leaders wanted more, and at Lahore in December 1929 the Congress adopted purna swaraj (complete independence)."),
    S(1, 2, "Freedom movement", "Who renounced his knighthood in protest against the Jallianwala Bagh massacre?",
      ["Rabindranath Tagore", "Mahatma Gandhi", "Jawaharlal Nehru", "Gopal Krishna Gokhale"],
      "Rabindranath Tagore wrote to the Viceroy in May 1919 giving up the knighthood conferred on him in 1915. Gandhiji returned his Kaisar-i-Hind medal in 1920 during the Khilafat and Non-Cooperation campaign."),
    S(1, 2, "Freedom movement", "The Lahore session of the Indian National Congress in December 1929 is remembered because it:",
      ["Adopted complete independence (purna swaraj) as its goal", "Founded the Muslim League", "Accepted the partition of Bengal", "Began the Quit India Movement"],
      "At Lahore the Congress resolved on purna swaraj and called for 26 January 1930 to be observed as Independence Day. That date was later chosen for the Constitution to come into force in 1950."),
    S(1, 2, "Constitution", "Who moved the Objectives Resolution in the Constituent Assembly on 13 December 1946?",
      ["Jawaharlal Nehru", "B. R. Ambedkar", "Rajendra Prasad", "Sardar Vallabhbhai Patel"],
      "Nehru's Objectives Resolution, adopted in January 1947, set out the ideals that later became the Preamble. Ambedkar chaired the Drafting Committee and Rajendra Prasad presided over the Assembly."),
    S(1, 2, "Constitution", "The Preamble describes India as a republic. This means that:",
      ["The head of state is elected and not a hereditary monarch", "India has no official religion", "India has two levels of government", "Every citizen must vote"],
      "In a republic the head of state, here the President, is elected for a fixed term rather than inheriting the office. Having no state religion is what 'secular' means, and two levels of government is federalism."),
    # ---------- Practice Test 2 ----------
    S(2, 2, "Ancient India", "Which Chola king built the Brihadisvara temple at Thanjavur?",
      ["Rajaraja I", "Rajendra I", "Karikala", "Kulottunga I"],
      "Rajaraja I completed the great temple at Thanjavur in about 1010 CE. His son Rajendra I built a new capital, Gangaikonda Cholapuram, after his northern campaign."),
    S(2, 2, "Medieval India", "The Ashtapradhan was:",
      ["Shivaji's council of eight ministers", "Akbar's system of ranking officials", "A Vijayanagara temple tax", "The Sultanate's land revenue system"],
      "Shivaji's Ashtapradhan included the Peshwa (chief minister), the Senapati (commander) and six others. Akbar's ranking system was the mansabdari system."),
    S(2, 2, "Medieval India", "Which Mughal emperor abolished the jizya, the tax on non-Muslims, in 1564?",
      ["Akbar", "Babur", "Aurangzeb", "Jahangir"],
      "Akbar abolished the jizya in 1564, as part of his policy of treating all his subjects alike. Aurangzeb brought it back in 1679."),
    S(2, 2, "Ancient India", "The Ajanta cave paintings mainly show:",
      ["Scenes from the life of the Buddha and the Jataka tales", "Battles of the Mughal emperors", "Scenes from the Mahabharata war only", "Portraits of British officials"],
      "The Ajanta caves in Maharashtra are Buddhist monasteries and halls. Their wall paintings, mostly from the 5th century CE, illustrate the Buddha's life and the Jataka stories of his earlier lives."),
    S(2, 2, "Modern India", "Who called the Revolt of 1857 'the First War of Indian Independence' in a book of that name?",
      ["V. D. Savarkar", "Karl Marx", "R. C. Majumdar", "Jawaharlal Nehru"],
      "V. D. Savarkar's book The Indian War of Independence, 1857, written in 1909, called it the first war of independence. The historian R. C. Majumdar argued it was neither the first nor a national war of independence."),
    S(2, 2, "Modern India", "The Deccan Education Society, founded in Pune in 1884, counted which nationalist leader among its founders?",
      ["Bal Gangadhar Tilak", "Dadabhai Naoroji", "Surendranath Banerjee", "Lala Lajpat Rai"],
      "Tilak, Gopal Ganesh Agarkar and others had started the New English School in 1880 with Vishnushastri Chiplunkar; in 1884 they founded the Deccan Education Society, which set up Fergusson College in 1885. Naoroji and Banerjee were early Congress leaders from Bombay and Bengal, and Lajpat Rai was from Punjab."),
    S(2, 2, "Freedom movement", "Who was the first Indian elected to the British House of Commons?",
      ["Dadabhai Naoroji", "Surendranath Banerjee", "Pherozeshah Mehta", "Badruddin Tyabji"],
      "Dadabhai Naoroji won Finsbury Central in 1892. His 'drain theory' argued that British rule drained India's wealth."),
    S(2, 2, "Freedom movement", "In which year was Subhas Chandra Bose elected president of the Indian National Congress at its Haripura session?",
      ["1938", "1929", "1942", "1931"],
      "Bose presided over the Haripura session in February 1938. He was re-elected in 1939 at Tripuri but resigned after differences with Gandhiji and formed the Forward Bloc."),
    S(2, 2, "Constitution", "How many Schedules did the Constitution of India have when it came into force in 1950?",
      ["8", "12", "10", "6"],
      "The original Constitution had 8 Schedules. Amendments have since added the 9th (1951), 10th (1985, anti-defection), 11th (1992, panchayats) and 12th (1992, municipalities), making 12."),
    S(2, 2, "Constitution", "The idea of a single citizenship for the whole country, as in the Constitution of India, was taken from the constitution of:",
      ["Britain", "the United States", "Canada", "Ireland"],
      "Like Britain, India has one citizenship for the whole country. The United States has dual citizenship, of the federation and of each state. Directive Principles were borrowed from Ireland."),
    # ---------- Drill only ----------
    S(0, 2, "Ancient India", "Under whose direction were the first excavations at Harappa carried out in 1921?",
      ["Daya Ram Sahni", "R. D. Banerji", "Mortimer Wheeler", "James Prinsep"],
      "Daya Ram Sahni excavated Harappa in 1921; R. D. Banerji began work at Mohenjo-daro in 1922. Mortimer Wheeler dug at both sites later, at Harappa in 1946 and at Mohenjo-daro in 1950."),
    S(0, 2, "Freedom movement", "The Hindustan Socialist Republican Association, to which Bhagat Singh and Chandrashekhar Azad belonged, was given that name in:",
      ["1928", "1919", "1935", "1942"],
      "The Hindustan Republican Association was renamed the Hindustan Socialist Republican Association at a meeting at Feroz Shah Kotla in Delhi in September 1928."),
]
